entries[12162] = { ["name"] = "Pläne: Gehärtetes Eisenkurzschwert", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines gehärteten Eisenkurzschwerts.\nBenötigt Klassische Schmiedekunst (160)\nVerkaufspreis:\nGehärtetes Eisenkurzschwert\nWird beim Anlegen gebunden\nEinhändig Schwert\n3 - 5 Schaden Geschwindigkeit 2.60\n(1.5 Schaden pro Sekunde)\n+1 [Beweglichkeit oder Stärke]\nHaltbarkeit 75 / 75\nVerkaufspreis:\nBenötigt Eisenbarren (6), Starker Fluxus (2), Schwerer Schleifstein , Geringer Mondstein (2), Schweres Leder (3)\nOptionale Reagenzien: [] (#48)" }
