entries[12164] = { ["name"] = "Pläne: Massive Eisenaxt", ["text"] = "Benutzen: Lehrt Euch die Herstellung einer massiven Eisenaxt.\nBenötigt Klassische Schmiedekunst (185)\nVerkaufspreis:\nMassive Eisenaxt\nWird beim Anlegen gebunden\nZweihändig Axt\n5 - 10 Schaden Geschwindigkeit 3.60\n(2.1 Schaden pro Sekunde)\n+4 Stärke\n+3 Ausdauer\nHaltbarkeit 85 / 85\nVerkaufspreis:\nBenötigt Eisenbarren (14), Starker Fluxus (2), Schwerer Schleifstein (2), Goldbarren (4), Schweres Leder (2)\nOptionale Reagenzien: [] (#48)" }
