entries[12302] = { ["name"] = "Zügel des uralten Frostsäblers", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren uralten Frostsäbler oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Am Fehlen von Flecken oder Streifen kann man klar erkennen, dass dies der Nachfahre einer der ältesten Frostsäblerfamilien ist.\"\nKlassisch" }
