entries[13309] = { ["name"] = "Bauplan: Liebevoll hergestelltes Schießeisen", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines liebevoll hergestellten Schießeisens.\nBenötigt Klassische Ingenieurskunst (120)\nVerkaufspreis:\nLiebevoll hergestelltes Schießeisen\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n3 - 7 Schaden Geschwindigkeit 3.00\n(1.7 Schaden pro Sekunde)\n+3 Beweglichkeit\n+4 Ausdauer\nHaltbarkeit 75 / 75\nVerkaufspreis:\nBenötigt Bronzeröhre (2), Eine Handvoll Kupferbolzen (2), Schwerer Griff , Moosachat (3)\nOptionale Reagenzien: [] (#47)" }
entries[13310] = { ["name"] = "Bauplan: Genaues Zielfernrohr", ["text"] = "Benutzen: Lehrt Euch die Herstellung eines genauen Zielfernrohrs.\nBenötigt Klassische Ingenieurskunst (180)\nVerkaufspreis:\nGenaues Zielfernrohr\nBenutzen: Bringt dauerhaft ein Zielfernrohr an einem Bogen oder einer Schusswaffe an, das den damit verursachten Schaden um 2 erhöht.\n\nDurch das Anbringen des Fernrohrs an einer Distanzwaffe wird diese seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:\nBenötigt Bronzeröhre , Jade , Citrin" }
