entries[13335] = { ["name"] = "Zügel des Todesstreitrosses", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man das Ross von Totenschwur beschwört.\nBeschwört Baron Totenschwurs Todesstreitross oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Als Baron Totenschwur zum Champion der Geißel wurde, hat er sein liebstes Pferd dazu verdammt, ihn im Untod zu begleiten.\"\nBeute von:\nBaron Aurius Totenschwur\nOrt:\nStratholme" }
